//
// The EBML/Matroska element table (chapter 08 §8.6.7, WI-4.200). The table itself, kEbmlElements, is generated by
// tools/gen_ebml_schema.py into ebml_schema.gen.cpp from the IETF CELLAR schemas; lookup() is in ebml_schema.cpp.

#ifndef OVT_CONTAINER_EBML_EBML_SCHEMA_H
#define OVT_CONTAINER_EBML_EBML_SCHEMA_H

#include <cstddef>
#include <cstdint>
#include <span>

namespace ovt::container::ebml {

// The schema `type` of an element (RFC 8794 §7).
enum class EbmlType : uint8_t { Master, UInteger, Integer, Float, String, Utf8, Date, Binary };

struct EbmlElementDef {
  uint32_t id;       // with the length marker, e.g. 0x1A45DFA3
  const char* name;  // "Segment"
  EbmlType type;
  const char* path;           // "\Segment\Info"; `+` marks a recursive element, `(1-)`/`(-)` a global one, verbatim
  int min_occurs;             // 0 when the schema has no minOccurs
  int max_occurs;             // -1 = unbounded (no maxOccurs in the schema)
  const char* default_value;  // as written in the schema (floats as hex floats); nullptr = none
  bool unknown_size_allowed;
};

// Generated, sorted by id, ids unique.
extern const EbmlElementDef kEbmlElements[];
extern const std::size_t kEbmlElementCount;

[[nodiscard]] inline std::span<const EbmlElementDef> ebml_elements() noexcept {
  return {kEbmlElements, kEbmlElementCount};
}

// The definition of `id` (length marker included), or nullptr for an id the schemas do not define.
[[nodiscard]] const EbmlElementDef* lookup(uint32_t id) noexcept;

}  // namespace ovt::container::ebml

#endif  // OVT_CONTAINER_EBML_EBML_SCHEMA_H
